ep_contact_submit.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

let req = params;
let body = req.body ?? {};
let name = str(body.name ?? req.name ?? "Anonymous").trim();
let emailAddr = str(body.email ?? req.email ?? "").trim();
let subject = str(body.subject ?? req.subject ?? "Website Contact Form").trim();
let message = str(body.message ?? req.message ?? "").trim();
let dryRun = body.dryRun == true || req.dryRun == true;

if (emailAddr == "" || message == "") {
  return {ok: false, statusCode: 400, reason: "email and message are required"};
}

let messageId = str(body.messageId ?? req.messageId ?? "").trim();
if (messageId == "") {
  messageId = crypto.uuid();
}

let nowTs = datetime.now().isoformat();
let messages = vdb.collection("contact_messages");
let doc = {
  messageId: messageId,
  name: name,
  email: emailAddr,
  subject: subject,
  message: message,
  createdAt: nowTs
};

let host = str(service.env.EMAIL_SMTP_HOST ?? "").trim();
let smtpUser = str(service.env.EMAIL_SMTP_USERNAME ?? "").trim();
let smtpPass = str(service.env.EMAIL_SMTP_PASSWORD ?? "").trim();
let fromAddr = str(service.env.EMAIL_FROM ?? smtpUser).trim();
let toAddr = str(service.env.EMAIL_TO ?? "").trim();
let outbound = "New contact submission\n\nName: " + name + "\nEmail: " + emailAddr + "\nSubject: " + subject + "\nMessage:\n" + message;

if (dryRun) {
  return {
    ok: true,
    dryRun: true,
    messageId: messageId,
    stored: false,
    emailReady: !(host == "" || smtpUser == "" || smtpPass == "" || fromAddr == "" || toAddr == ""),
    preview: doc
  };
}

let saveRes = messages.insert(doc);
if (saveRes.ok == false) {
  return {ok: false, statusCode: 500, reason: saveRes.error ?? "Failed to persist contact message", messageId: messageId, result: saveRes};
}

if (host == "" || smtpUser == "" || smtpPass == "" || fromAddr == "" || toAddr == "") {
  return {
    ok: false,
    statusCode: 500,
    saved: true,
    messageId: messageId,
    status: "error",
    reason: "Missing SMTP environment values",
    error: "Set EMAIL_SMTP_HOST, EMAIL_SMTP_USERNAME, EMAIL_SMTP_PASSWORD, EMAIL_FROM, EMAIL_TO in metadata.env"
  };
}

let emailResult = email.send({
  host: host,
  port: service.env.EMAIL_SMTP_PORT ?? 587,
  startTls: service.env.EMAIL_SMTP_STARTTLS ?? true,
  ssl: service.env.EMAIL_SMTP_SSL ?? false,
  auth: service.env.EMAIL_SMTP_AUTH ?? true,
  username: smtpUser,
  password: smtpPass,
  from: fromAddr,
  to: [toAddr],
  subject: "[Contact] " + subject,
  body: outbound
});

return {
  ok: emailResult.ok == true,
  saved: true,
  messageId: messageId,
  status: emailResult.status,
  request: {name: name, email: emailAddr, subject: subject},
  email: emailResult.data,
  error: emailResult.error
};

